UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Centipedes, Millipedes, Kissing Bugs, Blister Beetles","body":"**Less venomous arthropods rarely cause systemic toxicity.** [1,2,10]\n\n**Centipede bite:** [1]\n- Severe, sharp local pain (worse than wasp)\n- Erythema, swelling, occasional lymphangitis\n- Treatment: hot water immersion (40-45°C), NSAIDs, opioids if needed, wound care, tetanus\n- Resolves over hours-days; rarely systemic\n\n**Millipede contact:** [1]\n- Defensive secretion = chemical irritant (benzoquinones)\n- Brown-black skin staining, burning sensation, blistering\n- Treatment: copious irrigation with soap and water, topical steroid, supportive\n- Eye exposure → ophthalmology consult (potential conjunctivitis, keratitis)\n\n**Kissing bug (*Triatoma*, vector of Chagas):** [1]\n- Painless nocturnal bite, often clusters on face/extremities\n- Local urticarial or papular reaction\n- Risk: **Chagas disease (*Trypanosoma cruzi*)** in endemic areas (Central/South America, southern US) — usually asymptomatic acutely but can cause cardiomyopathy decades later\n- Test serology if endemic exposure, consider in transplant/immunocompromised patients\n\n**Blister beetle (*Meloidae*):** [1]\n- Contact with crushed beetle → cantharidin → painful blistering 24-48 h later\n- Treatment: cool compresses, topical steroid, NSAIDs; do NOT unroof blisters\n\n**Treatment principles:**\n- Wound care, tetanus, NSAIDs\n- No antivenoms exist for these\n- Discharge with return precautions for spreading infection or systemic symptoms","citation":[1,2,10],"next":"te-dispo-discharge","summary":"Centipede: hot water + analgesia; millipede: irrigate, watch eyes; kissing bug: consider Chagas if endemic; blister beetle: cool compress, no unroofing."}'::jsonb
WHERE id = 'te-other' AND tree_id = 'terrestrial-envenomation';

